CREATE TABLE RecipeRepost (userId TEXT NOT NULL,recipeId TEXT NOT NULL,createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(userId,recipeId),FOREIGN KEY(userId) REFERENCES User(id) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY(recipeId) REFERENCES Recipe(id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX RecipeRepost_recipeId_idx ON RecipeRepost(recipeId);
